import{_ as t,o,c as s,a2 as i}from"./chunks/framework.Boholvbs.js";const u=JSON.parse('{"title":"Docs versions & release policy","description":"How PrioriCode documentation maps to releases: living docs on the latest line, versioned snapshots per release line, and how to tell what your build matches.","frontmatter":{"title":"Docs versions & release policy","description":"How PrioriCode documentation maps to releases: living docs on the latest line, versioned snapshots per release line, and how to tell what your build matches."},"headers":[],"relativePath":"support/versions.md","filePath":"support/versions.md"}'),a={name:"support/versions.md"};function n(r,e,l,d,h,c){return o(),s("div",null,[...e[0]||(e[0]=[i('<p>Short answer: <strong>the docs you&#39;re reading track the latest release of PrioriCode, always.</strong> The version selector in the header exists for when you&#39;re stuck on an older line — or need to check what changed between lines.</p><h2 id="the-model" tabindex="-1">The model <a class="header-anchor" href="#the-model" aria-label="Permalink to &quot;The model&quot;">​</a></h2><p>PrioriCode ships small and often: every release is a <strong>+1 patch</strong> (<code>v0.1.11 → v0.1.12 → …</code>), cut automatically when verified work lands on <code>main</code>. Documentation follows a matching discipline:</p><table tabindex="0"><thead><tr><th>Thing</th><th>Where it lives</th><th>Cadence</th></tr></thead><tbody><tr><td><strong>These docs</strong></td><td>This site (<code>packages/docs</code>)</td><td>Updated in the <em>same commit</em> as the change they describe — feature, flag, default, all of it.</td></tr><tr><td><strong>Release notes</strong></td><td><a href="https://github.com/Prioritech-Indonesia-Optima/prioricode/releases" target="_blank" rel="noreferrer">GitHub Releases</a></td><td>Generated per release: the raw list of what shipped, newest first.</td></tr><tr><td><strong>Versioned doc lines</strong></td><td>The docs version selector</td><td>One entry per <strong>minor release line</strong> (<code>v0.1</code>, later <code>v0.2</code>, <code>v1.0</code>). Snapshots of the whole site at the moment a line ends.</td></tr></tbody></table><p>Patch releases don&#39;t get their own docs version — a dropdown with forty near-identical entries isn&#39;t granularity, it&#39;s noise. The living docs <em>are</em> the patch history, kept honest by the same-commit rule.</p><h2 id="am-i-reading-the-right-docs-for-my-build" tabindex="-1">Am I reading the right docs for my build? <a class="header-anchor" href="#am-i-reading-the-right-docs-for-my-build" aria-label="Permalink to &quot;Am I reading the right docs for my build?&quot;">​</a></h2><p>Check your build:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">prioricode</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre></div><p>Compare against the latest release on GitHub (or let the updater tell you — it pings within seconds of launching when something newer exists). If your build is older than the docs you&#39;re quoting:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">prioricode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upgrade</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # or: prioricode upgrade &lt;target&gt;</span></span></code></pre></div><p>Rules of thumb:</p><ul><li><strong>Something in the docs doesn&#39;t exist in your build</strong> → you&#39;re behind, or the feature is experimental (those pages say so loudly, flag included).</li><li><strong>Your build does something the docs don&#39;t mention</strong> → that&#39;s a docs bug. We hold this repo to the same-commit rule; open an issue and it counts.</li><li><strong>You&#39;re pinned to an old release line on purpose</strong> → pick it from the docs version selector (where multiple lines are published); the snapshot from the end of that line is what you&#39;ll read.</li></ul><h2 id="how-a-line-gets-archived" tabindex="-1">How a line gets archived <a class="header-anchor" href="#how-a-line-gets-archived" aria-label="Permalink to &quot;How a line gets archived&quot;">​</a></h2><p>When <code>v0.1.x</code> ends and a new line (<code>v0.2</code>) begins:</p><ol><li>The current docs tree is copied into a version folder (<code>v0.1/</code>) in the docs source.</li><li>A <code>v0.1</code> entry joins the version selector pointing at that snapshot, no longer <code>default</code>.</li><li>Root docs continue as the living <code>v0.2</code> line.</li></ol><p>Nothing in a snapshot is edited afterward; corrections happen on the living line. That way &quot;what did the docs say back then&quot; stays answerable, and &quot;what is true now&quot; stays single-sourced.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Release lines move when <em>you</em> decide they should: patch is automatic, minor/major bumps are explicitly requested in this project&#39;s publish pipeline. The docs switcher follows the same rule.</p></div><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./../getting-started/install.html">Installation</a> — Upgrade, pin a version, or install by hand. <ul><li><a href="./troubleshooting.html">Troubleshooting</a> — When reality and docs disagree.</li><li><a href="./../reference/cli.html">CLI reference</a> — What ships in this release line, exactly.</li></ul></li></ul>',19)])])}const g=t(a,[["render",n]]);export{u as __pageData,g as default};
